build.playwright_script:
import { chromium } from 'playwright';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';
const __dirname = dirname(fileURLToPath(import.meta.url));
async function main() {
  const htmlPath = join(__dirname, 'worksheet.html');
  const pdfPath = join(__dirname, 'worksheet.pdf');
  const browser = await chromium.launch({ args: ['--no-sandbox', '--disable-setuid-sandbox'] });
  const page = await browser.newPage();
  await page.goto('file://' + htmlPath, { waitUntil: 'networkidle' });
  await page.pdf({ path: pdfPath, format: 'A4', landscape: true, printBackground: true, margin: { top: '0', right: '0', bottom: '0', left: '0' } });
  await browser.close();
  console.log('PDF generated:', pdfPath);
}
main().catch((err) => { console.error('Error generating PDF:', err); process.exit(1); });

styles.css:
@page { size: A4 landscape; margin: 0; }
* { margin: 0; padding: 0; box-sizing: border-box; }
html, body { font-family: Arial, Helvetica, sans-serif; color: #111; }
.page { width: 297mm; height: 210mm; padding: 10mm 12mm; page-break-after: always; position: relative; display: flex; flex-direction: column; }
.page:last-child { page-break-after: auto; }
.head { border-bottom: 3px solid #111; padding-bottom: 4px; margin-bottom: 6px; }
.head h1 { font-size: 22px; letter-spacing: .3px; }
.head .sub { font-size: 12px; color: #444; margin-top: 1px; }
.nameline { font-size: 11px; color: #333; margin-top: 4px; }
.cols { display: flex; gap: 10px; flex: 1; }
.col { flex: 1; display: flex; flex-direction: column; gap: 7px; }
.box { border: 1.5px solid #111; border-radius: 5px; padding: 7px 9px; }
.box h2 { font-size: 13px; text-transform: uppercase; letter-spacing: .4px; margin-bottom: 4px; }
.box.tint { background: #f3f3f3; }
.note { font-size: 12px; line-height: 1.35; }
.eg { font-size: 12px; line-height: 1.5; }
.eg .lbl { font-weight: bold; }
.eg .math { font-family: "Cambria Math", Georgia, serif; }
.rule { color: #b00; font-weight: bold; }
ul.tight { margin-left: 16px; }
ul.tight li { font-size: 12px; line-height: 1.4; margin-bottom: 2px; }
.q { font-size: 12px; line-height: 1.45; }
.q .num { font-weight: bold; }
.expr { font-family: "Cambria Math", Georgia, serif; font-size: 14px; letter-spacing: .5px; }
.qrow { margin: 3px 0; }
.answerline { border-bottom: 1px solid #999; height: 14px; margin-top: 3px; }
.mistake { border: 1.5px solid #111; border-radius: 5px; padding: 6px 9px; margin-bottom: 6px; }
.mistake .claim { font-size: 12px; }
.mistake .claim .expr { font-weight: bold; }
.mistake .field { font-size: 11px; color: #333; margin-top: 4px; }
.mistake .field .fl { display: inline-block; min-width: 78px; font-weight: bold; }
.mistake .field .line { border-bottom: 1px solid #999; display: inline-block; width: 70%; height: 13px; vertical-align: bottom; }
sup { font-size: .72em; vertical-align: super; }
.foot { font-size: 9.5px; color: #777; position: absolute; bottom: 4mm; left: 12mm; }
.pg { font-size: 9.5px; color: #777; position: absolute; bottom: 4mm; right: 12mm; }
